(3, 'Legal Alert: \"Supply of Commercial Premises is not exempt from Value Added Tax,\" Court of Appeal Says', 'Godfrey Orina', '2025-04-03', '1743701094326.jpg', '<p class=\"ql-align-justify\"><span class=\"ql-font-serif\">The Court of Appeal in </span><strong class=\"ql-font-serif\"><em>Nairobi Civil Appeal No. 65 of 2019 Kenya Revenue Authority vs David Mwangi Ndegwa</em></strong><span class=\"ql-font-serif\"> has observed that the supply of commercial premises is not exempt from Value Added Tax.</span></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><span class=\"ql-font-serif\">The decision, delivered by a three-judge bench on </span><strong class=\"ql-font-serif\">21</strong><sup class=\"ql-font-serif\"><strong>st</strong></sup><strong class=\"ql-font-serif\"> March,</strong><span class=\"ql-font-serif\"> </span><strong class=\"ql-font-serif\">2025</strong><span class=\"ql-font-serif\"> gave a </span><strong class=\"ql-font-serif\">separate</strong><span class=\"ql-font-serif\"> interpretation of </span><strong class=\"ql-font-serif\">Section 5 of the Value Added Tax</strong><span class=\"ql-font-serif\"> as read with </span><strong class=\"ql-font-serif\">paragraph 8 Part II</strong><span class=\"ql-font-serif\">, thereby departing from the </span><strong class=\"ql-font-serif\">High Court’s</strong><span class=\"ql-font-serif\"> decision which had previously demanded that </span><strong class=\"ql-font-serif\">VAT was not applicable</strong><span class=\"ql-font-serif\"> in transactions involving the purchase and sale of land and residential premises. </span></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong class=\"ql-font-serif\">Section 5 of the Value Added Tax, Cap 476 Laws of Kenya</strong><span class=\"ql-font-serif\"> provides for the </span><strong class=\"ql-font-serif\">charging</strong><span class=\"ql-font-serif\"> of Value Added Tax; while the First Schedule to the Act provides for the </span><strong class=\"ql-font-serif\">supply of goods and services that are exempt from VAT</strong><span class=\"ql-font-serif\">. </span></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong class=\"ql-font-serif\">Paragraph 8 of Part 2 to the First Schedule</strong><span class=\"ql-font-serif\"> provides that the supply of the following services shall be exempt supplies:</span></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong class=\"ql-font-serif\">supply by way of sale, renting, leasing, hiring, letting of land or residential </strong> <strong class=\"ql-font-serif\">premises. </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><span class=\"ql-font-serif\">“</span><strong class=\"ql-font-serif\">residential premises</strong><span class=\"ql-font-serif\"> “means land or a building occupied or capable of being occupied as a residence, but not including hotel or holiday accommodation.</span></p><p class=\"ql-align-justify\"><span class=\"ql-font-serif\">Provided that this paragraph shall not apply where such services are supplied in respect of-</span></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong class=\"ql-font-serif\"><em>a.&nbsp;&nbsp;&nbsp;car park services; or</em></strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong class=\"ql-font-serif\"><em>b.&nbsp;&nbsp;&nbsp;conference or exhibition services, except where such services are provided for educational institutions as part of learning. </em></strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><span class=\"ql-font-serif\">The Court of Appeal noted that the High Court had relied on </span><strong class=\"ql-font-serif\">Article 260 of the Constitution</strong><span class=\"ql-font-serif\"> to define land but subsequently failed to appreciate that </span><strong class=\"ql-font-serif\">the said definition is neither precise nor immutable and was not intended</strong><span class=\"ql-font-serif\"> for all and sundry </span><strong class=\"ql-font-serif\">situations</strong><span class=\"ql-font-serif\"> and </span><strong class=\"ql-font-serif\">contexts.</strong><span class=\"ql-font-serif\">&nbsp;</span></p><p class=\"ql-align-justify\"><span class=\"ql-font-serif\">The court further stated that the </span><strong class=\"ql-font-serif\">VAT Act is an exemption statute</strong><span class=\"ql-font-serif\">, thus </span><strong class=\"ql-font-serif\">what is not exempted by the Act from levy of VAT is vatable</strong><span class=\"ql-font-serif\">. Consequently, the Court took the view that the </span><strong class=\"ql-font-serif\">exclusion</strong><span class=\"ql-font-serif\"> in Paragraph 8 of Part II of the First Schedule to the Act of supply of the class of premises known as </span><strong class=\"ql-font-serif\">“residential”</strong><span class=\"ql-font-serif\"> from levy of VAT, without any mention of supply of the class of premises known as “</span><strong class=\"ql-font-serif\">commercial,</strong><span class=\"ql-font-serif\">” </span><strong class=\"ql-font-serif\">must </strong><span class=\"ql-font-serif\">mean that unlike residential premises</span><strong class=\"ql-font-serif\">, SUPPLY OF COMMERCIAL PREMISES ARE NOT EXEMPT FROM VAT.&nbsp;</strong></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4, 'Threshold for Public Participation - County Governments', 'Godfrey Orina', '2025-04-07', '1744124305506.jpg', '<p class=\"ql-align-justify\"><strong>Public participation</strong> forms part of the <strong>core values and principles</strong> of governance under the Constitution of Kenya, 2010. Section 87 of the County Governments Act, Cap 265 Laws of Kenya provides for principles of citizen participation in counties. Further, <strong>Section 115 </strong>provides that public participation in the <strong>county planning processes</strong> shall be <strong>mandatory</strong> and facilitated through provision to the public of clear and unambiguous information on any matter under consideration in the planning process. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>What is public participation? </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">According to their plain and ordinary meaning, the words <strong>public involvement or public participation </strong>refers to the <strong>process</strong> by which the <strong>public participates in something.</strong> It is impossible to define the forms of facilitating appropriate degree of public participation, but as long as members of the public are accorded <strong>a reasonable opportunity</strong> to know about the <strong>issues</strong> at hand and make their contribution say on such issues, then it is possible to say that there is public participation.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Principles of citizen participation in counties</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Section 87 of the County Governments Act</strong> provides that citizen participation in counties shall be based upon the following principles: -</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">a.&nbsp;&nbsp;<strong>timely access</strong> to information, data, documents and other information relevant or related to policy formulation and implementation;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">b.&nbsp;&nbsp;<strong>reasonable access</strong> to the process of formulating and implementing policies, laws and regulations, including the approval of development proposals, projects and budgets, the granting of permits and establishment of specific performance standards;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">c.&nbsp;&nbsp;&nbsp;<strong>protection and promotion of the interests and rights of minorities</strong>, marginalized groups and communities and their access to relevant information;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">d.&nbsp;&nbsp;legal standing to interested or affected persons, organizations and where pertinent, communities, to appeal from or review decisions, or redress grievances, with particular emphasis on persons and traditionally marginalized communities, including women, the youth, and disadvantaged communities;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">e.&nbsp;&nbsp;&nbsp;<strong>reasonable balance</strong> in the roles and obligations of county governments and non-state actors in decision making processes to promote shared responsibility and partnership and to provide complementary authority and oversight;</p><p class=\"ql-align-justify\">f.&nbsp;&nbsp;&nbsp;&nbsp;<strong>promotion of public private partnerships</strong>, such as joint committees, technical teams and citizen commissions, to encourage direct dialogue and concerted action on sustainable development; and</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">g.&nbsp;&nbsp;recognition and promotion of <strong>the reciprocal roles of non-state actors’ participation and governmental facilitation and oversight</strong>. </p><p>&nbsp;</p><p class=\"ql-align-justify\"><strong>Judicial Interpretation on threshold for public participation. </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Time and again, Courts have given interpretations on what constitutes public participation. In the case <strong><em><u>of Mugo &amp; 14 Others vs. Matiang’i &amp; Anor; Independent Electoral and Boundary Commission of Kenya &amp; 19 Others (Interested Party) Constitutional Petition No. 4 of 2019</u></em></strong>, the court observed that for the principle of public participation to be met, the following parameters are required: -</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;there has to be <strong>evidence of inclusivity</strong>, that’s to say, all stakeholders or those affected by an administrative policy, or law have to be given an opportunity to express or ventilate their views well aware of what is at stake.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;ii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the affected people have to be given <strong>sufficient notice of the nature of the decision to be made and when consultations will be held</strong>. The information has to be disseminated through public barazas, churches, mosques, print and electronic media and other avenues to ensure that the information reached the targeted audience.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the government agency or a public officer in charge of the programme of public participation has to be of essence take into account public participation of the governed in quantitative as well as qualitative way i.e <strong>the engagement has to be meaningful and done in good faith rather than a mere formality.</strong></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;iv.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;public participation calls for innovation and some level of malleability depending on the <strong>nature of subject</strong> matter for example culture, geographical issues, logistical constraints. The test to be applied is effectiveness and efficiency. The question to be asked is, was the mechanism effective in achieving sufficient public participation?</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;v.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;public <strong>participation does not mean that everyone has to give their views on the issue at hand as to attain such a standard at times could be impractical.</strong> A public participation exercise has to however show intentional inclusivity and diversity. A programme of public participation should not disregard bona fide major stakeholders otherwise the program would be ineffective and illegal. Those mostly affected by the policy are expected to have a bigger say in that policy, legislation or action and their views have to be sought, taken into account. The view of major stakeholders has to be captured through minutes or any other proof that shows that their views are captured and have a bearing in the final decision.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;vi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>public participation is not a public relations exercise. It has to be meaningful and done in good faith</strong>. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>G.M Orina &amp; Co. Advocates</strong> gives <strong>advisories</strong> to county governments on matters touching on public participation, <strong>drafts public participation laws and polices</strong> on behalf of County governments and <strong>offers representation</strong> in courts on matters relating to or incidental to public participation.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">For more information and/or assistance in matters relating to public participation, contact us via <a href=\"mailto:info@gmorinaadvocates.com/gmorinaadvocates@gmail.com\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinaadvocates.com/gmorinaadvocates@gmail.com</strong></a><strong> and/or +254786437754.</strong></p><p class=\"ql-align-justify\">All rights reserved for <strong>G.M ORINA &amp; CO. ADVOCATES.</strong> </p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5, 'Electoral Reforms in Kenya', 'Godfrey & Immer', '2025-04-08', '1744190555341.avif', '<p class=\"ql-align-justify\">Electoral reform attributes to the <strong>nature</strong> and <strong>structure</strong> of <strong>institutions</strong> engaged in <strong>electoral management or delivering electoral services</strong>. Electoral reform in Kenya has been a long-standing issue, with <strong>periodic calls for change</strong> dating back several decades. The quest for <strong>a more transparent, inclusive</strong>, and <strong>effective electoral system</strong> has become increasingly urgent in recent years. This urgency has been spurred by the <strong>contentious 2007 post-election violence</strong>, the <strong>subsequent reform efforts</strong>, and the <strong>repeated concerns</strong> over <strong>electoral fairness</strong>, <strong>transparency, and credibility</strong> in the <strong>management of elections</strong>. In response to these challenges, electoral reforms have taken center stage in the country’s political and legal discourse. However, while progress has been made, there remain significant challenges that continue to undermine the quality and effectiveness of the electoral process.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Historical Background and Need for Electoral Reform</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya’s electoral history has been <strong>marred by allegations of fraud, electoral violence, and a lack of transparency</strong>. For many years, the country’s elections were characterized by rigging, manipulation, and lack of proper electoral management. The 2007 general elections marked a turning point. The aftermath of this election saw widespread violence, which claimed the lives of over 1,000 people and displaced many others. The events highlighted the urgent need for comprehensive electoral reforms to restore confidence in the democratic process.</p><p class=\"ql-align-justify\">In 2010, the Constitution of Kenya was promulgated, providing <strong>a new framework</strong> for governance and establishing the <strong>Independent Electoral and Boundaries Commission (IEBC).</strong> The Constitution introduced several reforms aimed at <strong>addressing the challenges experienced in previous elections.</strong> However, despite these measures, electoral reforms remain a work in progress, as each election cycle presents new challenges that test the resilience of the electoral system.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Key Areas of Electoral Reform in Kenya</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Several key areas have been identified for reform in Kenya’s electoral system, each of which requires focused attention to improve <strong>the integrity and efficiency of elections</strong>. One of the most significant reforms in Kenya has been the establishment of the Independent Electoral and Boundaries Commission (IEBC). The IEBC is responsible for <strong>overseeing the electoral process,</strong> including <strong>voter registration, the management of elections, and the declaration of results</strong>. However, questions about the independence of the IEBC persist, particularly regarding its ability to operate <strong>without external political pressure</strong>. Reforming the IEBC to ensure that it is truly independent, free from political influence, and equipped with adequate resources is essential for credible elections. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Moreover, there have been calls for greater transparency in how the IEBC conducts its operations, such as how it hires staff, procures election materials, and manages election results. Ensuring that the electoral management body operates transparently and independently is crucial in restoring faith in the electoral process.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Voter registration</strong> has been another area of focus in Kenya’s electoral reform discussions. The need for <strong>an accurate and updated voters\' register</strong> is critical to ensuring that all eligible voters can participate in elections. While Kenya has made significant strides in improving voter registration, there have been instances where eligible voters have been left out, particularly marginalized groups, such as internally displaced persons, persons with disabilities, and youth in remote areas. To enhance inclusivity, reforms aimed at improving <strong>the accessibility of voter registration</strong> centers and ensuring that the registration process is free from manipulation are necessary. It is also vital to implement a system that can allow for continuous voter registration, rather than only during election periods, so that all eligible voters are consistently captured in the national register.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The <strong>use of technology in elections</strong>, particularly the introduction of the <strong>electronic voter identification system (the Kenya Integrated Election Management System - KIEMS)</strong> in 2022, has been a notable innovation in Kenya’s electoral system. This system was designed to improve <strong>the speed, accuracy, and transparency of the voting process</strong>, from voter identification to the transmission of results. However, challenges such as system failures, glitches, and cyber vulnerabilities have raised concerns over the effectiveness of technology in elections. There is a need for <strong>continued investment in technology, with a focus on improving the reliability of the systems, ensuring secure data transmission, and addressing cybersecurity threats</strong>. Additionally, transparency in how technological tools is used, including audits of electronic voting systems and results transmission, is essential to building trust in the electoral process.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Electoral violence continues to be a significant challenge in Kenya’s elections. The violence that followed the 2007 election brought into sharp focus the need for reforms aimed at preventing such outbreaks. <strong>The security apparatus must be reformed</strong> to handle election-related violence proactively, ensuring that there is adequate preparedness to manage flashpoints and address the root causes of conflict, <strong>including ethnic divisions, political incitement, and disputes over results. The role of security forces in safeguarding the elections must also be emphasized, ensuring that they act impartially and are well-trained to handle election-related</strong> security issues in a professional and non-partisan manner.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya’s electoral reforms have been a step in the right direction, but much more needs to be done to ensure that the country’s electoral system is fair, transparent, and free from manipulation. The challenges of electoral management, voter registration, technological reliability and electoral violence require sustained efforts from both the government and civil society to address. Reforming the electoral system is not just about changing laws and structures; it is about creating an electoral culture that promotes democracy, inclusivity, and trust.</p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6, 'Registration of a Microfinance Institution in Kenya', 'Godfrey Orina', '2025-04-10', '1744308227058.jpg', '<p class=\"ql-align-justify\">Microfinance institutions (MFIs) play a crucial role in enhancing financial inclusion in Kenya. They provide essential financial services, such as <strong>savings, loans, and insurance</strong> to individuals and businesses that are typically <strong>underserved by commercial banks</strong>. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Central Bank of Kenya (CBK) is the <strong>regulatory authority</strong> overseeing the operations of MFIs. For an entity to operate as a microfinance institution in Kenya, it must adhere to <strong>specific legal requirements</strong> and obtain <strong>a license from the CBK</strong>. This article outlines the requirements for registering a microfinance institution (MFI) in Kenya, covering the essential aspects of the registration process under the <strong>Microfinance Act, Cap 493 C Laws of Kenya,</strong> its regulations, and the CBK regulations.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-center\"><strong>The Legal Framework for Microfinance Institutions in Kenya</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-justify\">The Microfinance Act, Cap 493C Laws of Kenya establishes the regulatory framework for microfinance institutions in Kenya. The act provides guidelines for the <strong>registration, licensing, and supervision of MFIs.</strong> The Central Bank of Kenya (CBK) is responsible for enforcing these regulations to ensure that MFIs operate in a financially sound manner and maintain public trust. In Kenya, microfinance institutions are categorized into two primary categories:</p><p class=\"ql-align-justify\">a)&nbsp;&nbsp;<strong>Deposit-Taking Microfinance Institutions (DTMs):</strong> These institutions can accept deposits from the public and offer loans and other financial services.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">b)&nbsp;&nbsp;<strong>Non-Deposit Taking Microfinance Institutions (NDTMs):</strong> These institutions provide loans and other financial services but do not accept deposits.</p><p class=\"ql-align-justify\">The registration process differs depending on whether the institution intend to accept deposits or not.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>General Requirements for Registration of Microfinance Institutions in Kenya</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The application process for registering a MFI in Kenya requires the intended institution to meet certain <strong>operational, legal, and financial criteria</strong>. An <strong>application for a licence</strong> to carry out deposit-taking business or non-deposit-taking microfinance business shall be made to the Central Bank of Kenya. The following are the key requirements for registration: The institution must be <strong>a Kenyan-registered company</strong>. This includes registering as a limited company under the Companies Act and ensuring that the business structure aligns with the Microfinance Act. The business name must include terms such as \"<strong>Microfinance</strong>\" or <strong>\"Deposit-Taking Microfinance</strong>\" for institutions that intend to accept deposits. This ensures that the institution is legally recognized and distinguishable from other financial service providers.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The institution must have <strong>sufficient share capital.</strong> The minimum capital requirements differ depending on whether the institution is a Deposit-Taking Microfinance Institution (DTM) or a Non-Deposit Taking Microfinance Institution (NDTM). A core capital of at least <strong>KES 60 million</strong> for general institutions while for deposit-taking microfinance businesses categorized under specific regulations, the core capital must be at least KES 20 million. These capital requirements help ensure that the institution has a solid financial foundation to support its operations.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">A comprehensive <strong>feasibility study</strong> and a three-year business plan are mandatory for registration. These documents should provide a detailed assessment of the proposed business operations, financial projections, and market analysis. The business plan must outline the institution\'s objectives, its target market, and its projected revenue streams. It should also detail the proposed organizational structure, governance model, and risk management strategies.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Key aspects of the business plan include: Mission, vision, and scope of the microfinance institution’s operations. Detailed analysis of the financial market, target clientele, and expected demand for services. Projections for the financial performance, including balance sheets, income statements, and cash flow for the first three years and information on the institution\'s governance structure, including the qualifications of directors and managers.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The institution must conduct a <strong>Fit and Proper Test</strong> for its <strong>proposed directors and key management personnel.</strong> This test is crucial to ensure that the individuals in charge of the institution are professionally qualified and have the necessary experience to manage the business in a <strong>sound and responsible manner</strong>. The Fit and Proper Test includes background checks to assess the individual’s Professional qualifications, Reputation, Integrity and Experience in financial management. The Central Bank of Kenya provides specific forms for this test, which must be completed and submitted as part of the registration application.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">DTMs must maintain <strong>sufficient liquidity levels</strong> to handle customer withdrawals and other operational requirements. The institution must submit projections for liquidity management, including cash flow, deposit mobilization strategies, and how it intends to maintain reserves.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The institution must further put in place internal control measures to <strong>monitor financial transactions and prevent fraud</strong>. These controls include having appropriate audit procedures, risk management protocols, and compliance measures. The Central Bank shall consider every application made and may, if satisfied that the applicant meets the requirements of the Act, grant a licence to the applicant upon payment of a prescribed fee. A licence issued under this Act shall, unless earlier revoked, be valid up to the 31st day of December of the year in which it is issued and may, on expiry, be <strong>renewed</strong> on application: provided that where an application for its renewal is made, the licence shall be deemed to continue in force until the application is determined.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Upon the application being submitted and reviewed by the Central Bank of Kenya, and upon the institution meeting all the necessary requirements, a license to operate as a microfinance institution is issued. After registration, the institution must comply with <strong>ongoing supervision</strong> by the CBK, including <strong>periodic audits and reports on its financial health, risk management practices, and compliance with regulations</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Registering a microfinance institution in Kenya involves a detailed and regulated process, ensuring that only financially stable and professionally managed institutions are licensed to operate. The Central Bank of Kenya plays a crucial role in ensuring that microfinance institutions maintain proper governance, financial stability, and compliance with relevant regulations. By meeting the registration requirements and adhering to the regulatory framework, microfinance institutions can contribute to Kenya’s economic growth by offering essential financial services to underserved communities, promoting financial inclusion, and supporting sustainable development.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">For more information and/or assistance in matters relating to registration of a micro-finance institution in Kenya, contact us via <a href=\"mailto:info@gmorinaadvocates.com/gmorinaadvocates@gmail.com\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinaadvocates.com/gmorinaadvocates@gmail.com</strong></a> and/or <strong>+254786437754.</strong> &nbsp;</p><p class=\"ql-align-justify\">All rights reserved for&nbsp;<strong>G.M ORINA &amp; CO. ADVOCATES.</strong></p><p class=\"ql-align-justify\">&nbsp;</p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7, 'Kenya’s Foreign Direct Investment Landscape', 'GM Orina', '2025-04-11', '1744394740252.jpg', '<p class=\"ql-align-justify\">Foreign Direct Investment (FDI) plays a key role in the <strong>economic development</strong> of many countries, Kenya included. As the largest economy in East Africa, emerges as an <strong>attractive destination</strong> for foreign investors, owing to its <strong>strategic location</strong>, <strong>diverse economy</strong> and <strong>relatively stable political environment</strong>. The <strong>legal framework</strong> governing Foreign Direct Investment (FDI) in Kenya is designed to <strong>promote investment while protecting the interests of both foreign investors and the country</strong>. This article delves into Kenya’s foreign investment landscape, analyzing the legal provisions, key regulations, and practical considerations for foreign investors interested in entering the Kenyan market.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-center\"><strong>Legal Framework Governing Foreign Direct Investment in Kenya</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-justify\">FDI refers to <strong>investments made by a foreign entity</strong> in a business located in another country, typically through <strong>acquisition of assets</strong>, <strong>establishment of subsidiaries</strong>, or <strong>participation in joint ventures</strong>. In Kenya, FDI contributes significantly to the country’s economic growth, particularly in <strong>industries</strong> such as <strong>agriculture, infrastructure, manufacturing, and services</strong>. Foreign investment in Kenya is largely attributed to the country’s <strong>ever-growing consumer market</strong>, <strong>favorable trade agreements</strong> and emerging industries such as <strong>technology, energy, and real estate</strong>. In 2020, Kenya ranked as one of the leading destinations for FDI in sub-Saharan Africa, with significant investments flowing into various sectors. The government has developed policies aimed at encouraging foreign investments, with several laws enacted to <strong>create a conducive environment</strong> for investors while safeguarding the country’s strategic interests.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>1.&nbsp;&nbsp;&nbsp;The Companies Act. </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Companies Act, 2015 is among <strong>key legislation</strong> for foreign investors seeking to operate in Kenya. The Act regulates <strong>the formation, registration, and operation of companies,</strong> including foreign-owned companies. Under the Act, foreign investors can incorporate a company in Kenya either as <strong>a wholly owned subsidiary</strong> or in <strong>partnership with a local partner</strong>. The registration process provides foreign entities with the legal recognition needed to do business in Kenya. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>2.&nbsp;&nbsp;&nbsp;The Foreign Investments Protection Act</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Foreign Investments Protection Act (FIPA) objective is to <strong>protect and promote foreign investments in Kenya</strong>. The law provides a framework for the protection of foreign investments by <strong>offering assurances that foreign investors</strong> will be treated <strong>fairly </strong>and that their investments will be <strong>safeguarded from nationalization or expropriation</strong>, except in cases of public interest, and with prompt and adequate compensation. FIPA further guarantees the <strong>free transfer of profits, dividends</strong> and other investment returns to the investor\'s home country thus allowing foreign investors to repatriate funds without restrictions.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>3.&nbsp;&nbsp;&nbsp;The Investment Promotion Act (IPA)</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Investment Promotion Act establishes the <strong>Kenya Investment Authority</strong>, which is tasked with <strong>promoting and facilitating both local and foreign investment</strong>. The law advocates for an <strong>investment-friendly environment</strong> by providing <strong>incentives for foreign</strong> investment and providing investors with the <strong>necessary permits, licenses, and approvals. </strong>The IPA provides various <strong>tax incentives</strong> for foreign investors, including <strong>tax holidays, exemptions on import duties for capital goods</strong> and <strong>investment allowances.</strong> These incentives are aimed at making Kenya an attractive investment destination.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">4.&nbsp;&nbsp;&nbsp;<strong>The Competition Act</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Competition Act regulates <strong>anti-competitive practices</strong> in Kenya and ensures that foreign direct investments <strong>do not undermine market competition</strong>. The Act <strong>prohibits monopolistic practices</strong> and <strong>promotes fair competition</strong>, ensuring that foreign investors cannot dominate the market at the expense of local players. The Competition Authority of Kenya (CAK) monitors compliance with the Act, <strong>reviewing mergers and acquisitions to ensure that they do not negatively affect market dynamics</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya’s economic diversification provides ample opportunities for foreign investors in a variety of sectors including <strong>Agriculture, Manufacturing, Information &amp; Technology Innovation, Energy &amp; Infrastructure. </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya’s foreign investment legal framework is designed to create an <strong>enabling environment</strong> for foreign direct investments. Key legal instruments such as the Companies Act, the Foreign Investments Protection Act and the Investment Promotion Act provide a solid basis for <strong>protecting the interests of foreign investors</strong> <strong>while encouraging economic growth.</strong> </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>G.M Orina &amp; Co. Advocates</strong> assists and partners with Clients to ensure <strong>regulatory compliance</strong> and protection on all spheres related to and incidental to Foreign Direct Investment. For further assistance, kindly contact us through <a href=\"mailto:info@gmorinaadvocates.com\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinaadvocates.com</strong></a><strong> and/or </strong><a href=\"mailto:gmorinaadvocates@gmail.com\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>gmorinaadvocates@gmail.com</strong></a><strong> and/or +254786437754</strong>. </p><p class=\"ql-align-justify\">All Rights Reserved – <strong>G.M Orina &amp; Co. Advocates</strong> </p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8, 'Africa\'s Trade Potential: Legal Framework and Opportunities for Growth', 'Godfrey Orina', '2025-04-16', '1744805060475.jpg', '<p class=\"ql-align-justify\">Africa is home to abundant <strong>natural resources, a growing consumer market, and a young and dynamic workforce</strong>. Despite these advantages, the continent has long struggled to tap into its full trade potential. However, recent developments in <strong>trade agreements, economic integration, and legal reforms</strong> are paving way for Africa to <strong>unlock its trade potential</strong> and <strong>boost its position</strong> in the global economy. This article explores Africa\'s trade potential from a legal perspective, examining <strong>the key legal framework, regional trade agreements</strong> and <strong>opportunities that exist to enhance intra-Africa trade and expand Africa\'s participation in the global trading system</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-center\"><strong>Overview of Africa\'s Trade Landscape</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-justify\">Africa, offers a diverse market with a population of over 1.2 billion people. It contains some of the <strong>world’s richest reserves of minerals</strong>, <strong>oil, and natural gas,</strong> alongside significant agricultural resources. Despite the immense wealth, Africa has long faced challenges in <strong>realizing</strong> its trade potential, primarily due to barriers such as <strong>poor infrastructure, regulatory fragmentation, and political instability</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Recent efforts to boost intra-Africa trade have focused on <strong>creating a unified</strong> and <strong>more efficient legal and regulatory framework</strong> to improve trade flows across the continent. Central to these efforts are <strong>regional trade agreements</strong> that aim to harmonize rules and <strong>facilitate greater economic cooperation</strong> among African countries.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>1.&nbsp;&nbsp;&nbsp;The African Continental Free Trade Area (AfCFTA)</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">One of the most significant legal developments in African trade is the <strong>African Continental Free Trade Area (AfCFTA),</strong> which came into force on <strong>January 1, 2021</strong>. The AfCFTA is the world’s largest free trade area by number of participating countries, comprising 54 of Africa\'s 55 member states. The AfCFTA <strong>aims to create a single market</strong> for goods, services, and investments, promoting intra-Africa trade and <strong>facilitating economic integration</strong> across the continent. </p><p class=\"ql-align-justify\">The AfCFTA has the potential to increase intra-Africa trade by over 50%, according to estimates by the <strong>United Nations Economic Commission for Africa (UNECA</strong>). The agreement seeks to <strong>reduce tariffs, eliminate non-tariff barriers, harmonize trade rules, and enhance the movement of goods and services across borders</strong>. One of the central legal frameworks under the AfCFTA is <strong>the Protocol on Trade in Goods</strong>, which seeks to <strong>eliminate tariffs on 90% of goods traded between member states</strong>. &nbsp;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Protocol on Trade in Services addresses barriers to trade in services, particularly in industries such as <strong>finance, telecommunications, and transport</strong>. It is expected that the liberalization of services will have significant economic benefits for African countries, creating new opportunities for trade and investment. AfCFTA also envisions the creation of a <strong>pan-African investment protocol</strong> aimed at boosting intra-Africa investment and <strong>easing restrictions on cross-border investments</strong>. Legal instruments under AfCFTA, including dispute resolution mechanisms, will play a critical role in <strong>promoting fairness and ensuring that countries adhere to agreed-upon terms</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>2.&nbsp;&nbsp;&nbsp;The Protocol on the Free Movement of Persons, the Right of Residence, and the Right of Establishment</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Protocol on the Free Movement of Persons under the African Union (AU) framework is a significant legal development aimed at <strong>facilitating the free movement of people across African borders</strong>.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[1]</a> While it is often seen as a complementary agreement to the AfCFTA, its significance lies in <strong>its potential to enhance labor mobility and entrepreneurship within the continent</strong>. By enabling Africans to move freely, the protocol promotes <strong>a deeper regional integration</strong> that allows for the <strong>exchange of skills, knowledge, and capital</strong>. It also <strong>supports the creation</strong> of <strong>a more dynamic and competitive labor force</strong>. The legal framework established under this protocol allows African citizens <strong>to travel, live, and work</strong> in any of the member states without the difficult visa and work permit requirements that typically hinder trade and investment.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>3.&nbsp;&nbsp;&nbsp;The East African Community (EAC) and The Economic Community of West African States (ECOWAS)</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Beyond the AfCFTA, there are several <strong>regional trade agreements</strong> that are pivotal to Africa’s trade potential, including the East African Community <strong>(EAC</strong>) and the Economic Community of West African States (<strong>ECOWAS</strong>). These regional trade blocs have established their own legal frameworks to <strong>promote trade and economic</strong> <strong>integration among their member states</strong>.<strong> </strong></p><p class=\"ql-align-justify\">The EAC is an economic bloc comprising six member states from East Africa. Through instruments, such as the <strong>EAC Customs Union</strong> and the EAC Common Market, the EAC <strong>facilitates free trade</strong> within its region by <strong>harmonizing tariffs, removing non-tariff barriers, and promoting economic cooperation</strong>.<strong> </strong>ECOWAS, which includes 15 West African countries advances and facilitates intra-regional trade. ECOWAS has implemented various protocols to liberalize trade, including <strong>the ECOWAS Trade Liberalization Scheme (ETLS</strong>), which allows for the <strong>duty-free movement</strong> of goods and services among its members.</p><p class=\"ql-align-center\"><strong>Opportunities for Africa\'s Trade Growth</strong></p><p class=\"ql-align-justify\">Africa’s <strong>agricultural sector</strong> is one of the continent’s most promising areas for trade growth. With <strong>vast arable land</strong> and an abundance of resources, Africa has the potential to become <strong>a leading exporter of agricultural products</strong> such as <strong>coffee, cocoa, tea, and vegetables</strong>. Legal instruments such as the <strong>Comprehensive Africa Agriculture Development Program (CAADP)</strong> have provided a roadmap for the growth of agriculture, enhancing trade potential within Africa and globally. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Further, Africa holds over 30% of the world’s mineral resources, including oil, gold, diamonds, and rare earth minerals. Legal agreements facilitating the export of these resources, along with favorable regulations, could significantly boost Africa\'s trade potential.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The <strong>technology sector</strong> in Africa is rapidly growing, with African countries like Kenya, Nigeria, and South Africa becoming technology hubs. Legal frameworks under AfCFTA, along with initiatives such as the <strong>Digital Transformation Strategy for Africa,</strong> are creating <strong>favorable environments for e-commerce, mobile technology, and innovation</strong>. Additionally, the legal framework supporting digital platforms and fintech can help bridge the gap in access to financial services, enabling the growth of digital trade and financial inclusion across the continent.</p><p class=\"ql-align-justify\">Africa is rich in <strong>cultural heritage</strong> <strong>and diverse ecosystems,</strong> making it a leading global tourist destination. Frameworks such as the Protocol on the Free Movement of Persons have the potential to boost the tourism sector by making travel across borders more accessible and affordable.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">With growing urbanization and a burgeoning middle class, there is significant demand for services such as <strong>banking, telecommunications, education and healthcare.</strong> Frameworks under the AfCFTA and regional bodies like EAC and ECOWAS are essential for liberalizing services and enhancing Africa’s competitiveness in the global market.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Despite the positive development, several challenges hinder <strong>Africa’s ability to fully realize its trade potential. </strong>Poor infrastructure hampers trade across the continent. The legal framework for infrastructure development must p<strong>rioritize investment in trade-related infrastructure. </strong>Political instability in certain regions can deter foreign investment and disrupt trade. <strong>Strong legal and political frameworks</strong> are necessary to ensure a stable and predictable trading environment. While many African countries have signed trade agreements such as the AfCFTA, <strong>the implementation</strong> of these agreements at the national level remains a challenge. Harmonizing local laws with regional and international agreements is crucial for smooth trade operations.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Africa’s trade potential is vast, and the continent stands on the cusp of a transformative period in global trade. Through legal frameworks like the AfCFTA, regional integration efforts, and the liberalization of trade in goods, services, and investment, Africa is poised to enhance intra-Africa trade, attract foreign investment, and expand its global trade footprint. However, realizing this potential requires overcoming challenges such as infrastructure deficits, governance issues, and legal harmonization. With continued legal reforms and strong political will, Africa can leverage its trade potential to spur sustainable economic growth and development.</p><p><br></p><p>  <a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[1]</a> Protocol to the Treaty Establishing the African Economic Community Relating to Free Movement of Persons, Right of Residence and Right of Establishment ( https://au.int/en/treaties/protocol-treaty-establishing-african-economic-community-relating-free-movement-persons)</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `articles` (`id`, `title`, `author`, `date`, `image`, `description`, `subtitle1`, `description1`, `desc1l1`, `desc1l2`, `desc1l3`, `desc1l4`, `desc1l5`, `subtitle2`, `description2`, `subtitle3`, `description3`, `desc3l1`, `desc3l2`, `desc3l3`, `desc3l4`, `desc3l5`, `description5`) VALUES
(9, 'Climate Change - Kenya\'s Story', 'Godfrey Orina', '2025-04-17', '1744890250361.jpg', '<p class=\"ql-align-justify\">Climate change means a <strong>change in the climate system</strong> which is caused by significant changes in the concentration of greenhouse gases <strong>as a consequence of human activities and which is in addition to natural climate change that has been observed during a considerable period. </strong></p><p class=\"ql-align-justify\">Climate change has emerged as one of <strong>the most critical global challenges</strong> of the <strong>21</strong><sup><strong>st</strong></sup><strong> century</strong>, with profound effects on ecosystems, economies, and human societies. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya, an emerging economy, faces significant challenges and opportunities in addressing climate change. Its vulnerability stems from <strong>dependence on agriculture</strong>, which is highly susceptible to <strong>climate variability</strong>, as well as from its location in the arid and semi-arid regions. As a response, Kenya has taken a <strong>proactive approach</strong> in integrating climate change into its legal and policy frameworks, recognizing both the need for mitigation and adaptation. This article delves into Kenya’s efforts to address climate change, with a special focus on the existing legal framework, Kenya’s obligations under international law, challenges faced and possible solutions on matters climate change. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-center\"><strong>The Legal Framework for Climate Change in Kenya</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-justify\"><strong>1.&nbsp;&nbsp;&nbsp;The Constitution of Kenya</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya’s legal framework on climate change is anchored in the Constitution of Kenya, 2010, which sets a solid foundation for <strong>environmental protection and the recognition of sustainable development</strong> as a constitutional imperative. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Under Article 42, the Constitution grants every citizen <strong>the right to a clean and healthy environment</strong>. This is a significant, as it mandates the state to <strong>ensure environmental protection</strong> and to <strong>promote sustainable development</strong> for current and future generations. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Article 69 of the Constitution outlines the obligations of the State in respect of the environment, to include <strong>ensuring sustainable exploitation, utilization, management and conservation of the environment and natural resources</strong>, and ensure the equitable sharing of accrued benefits. The constitutional protection has provided a strong basis for the development of Kenya’s climate change laws, positioning the country as one of the few African nations to integrate climate change into its <strong>national development agenda.</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>2.&nbsp;&nbsp;&nbsp;The Climate Change Act</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Climate Change Act aims to provide <strong>a regulatory framework</strong> for <strong>enhanced response to climate change</strong> and a <strong>mechanism and measure to achieve low carbon climate development. </strong>The Act creates a comprehensive framework for the <strong>governance of climate change and establishes mechanisms for coordination between different sectors and levels of government</strong>. Key provisions include the establishment of the National Climate Change Council under Section 5. This council is tasked with overseeing the <strong>country’s implementation of climate change policies</strong> and strategies, ensuring that climate change is incorporated in the national planning processes.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Act mandates the formulation and implementation of the National Climate Change Action Plan, a strategic document that <strong>outlines specific actions</strong> for <strong>adaptation and mitigation, focusing on sectors such as agriculture, water resources, energy, and health</strong>. The Act provides for the mobilization of financial resources for climate change initiatives through domestic and international funding sources and the establishment of a climate change fund under section 25 <strong>to support mitigation and adaptation programs</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>3.&nbsp;&nbsp;&nbsp;The Environmental Management and Coordination Act (EMCA)</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Environmental Management &amp; Co-ordination Act provides for the <strong>establishment of an appropriate legal and institutional framework for the management of the environment.</strong> The act provides that every citizen is entitled to a clean and healthy environment, and establishes the National Environment Management Authority which shall, formulate the National Environment Action Plan. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-center\"><strong>Kenya’s International Obligations on Climate Change</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-justify\">Kenya has actively participated in international efforts in dealing with climate change. As a signatory to the Paris Agreement, Kenya has committed to <strong>reducing greenhouse gas emissions</strong> and enhancing its adaptation efforts. Under the agreement, Kenya pledges to reduce emissions by 30% by the year 2030, </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Additionally, Kenya is signatory to the United Nations Framework Convention on Climate Change, UNFCCC, where it has undertaken to<strong> submit periodic reports</strong> on its <strong>progress in implementing climate change mitigation</strong> and adaptation strategies. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Despite the legal and policy frameworks on climate change in place, Kenya faces significant financial challenges in addressing climate change. The country’s inadequate financial capacity means that climate change mitigation and adaptation initiatives are often underfunded, hindering their implementation. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Whereas the Climate Change Act establishes coordination mechanisms, Kenya still challenges in <strong>ensuring that different sectors</strong> and levels of government <strong>effectively collaborate</strong> to implement climate action plans<strong>. Fragmentation and lack of synergy between institutions can delay the implementation of crucial climate policies</strong>. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">There is a need for <strong>enhanced capacity at both the national and local levels to implement and monitor climate change laws and policies</strong>. The lack of adequate technical expertise and resources at the grassroots level <strong>limits the effectiveness of climate change programs</strong>. While the Kenyan government has made efforts to integrate climate change into public discourse, there is still a need for <strong>greater awareness</strong> and understanding of climate change issues among the general public. Climate action initiatives require broad <strong>community participation</strong> to be successful.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-center\"><strong>Proposed Recommendations</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-justify\">1.&nbsp;&nbsp;&nbsp;<strong>Increased Funding for Climate Change Initiatives </strong>- The government should prioritize climate change financing, not only through international climate funds but also by strengthening domestic financial mechanisms for climate change programs. This could include leveraging the private sector and encouraging investments in green energy and climate-resilient agriculture.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">2.&nbsp;&nbsp;&nbsp;<strong>Enhanced Institutional Coordination and Monitoring</strong>- To ensure effective implementation, it is crucial that Kenya enhances coordination among its climate institutions. This may involve establishing clear and distinct functions and performance indicators for various stakeholders and improving monitoring and evaluation mechanisms.</p><p>&nbsp;</p><p class=\"ql-align-justify\">3.&nbsp;&nbsp;&nbsp;<strong>Extensive Public education on Climate Change</strong>: - There is a need for extensive public education on climate change, its impacts, and how citizens can contribute to mitigating and adapting to it. <strong>Schools, media, and community programs</strong> could play a pivotal role in building knowledge about climate change. Building local capacity through training programs for government officials, community leaders, and technical experts is vital for improving the implementation of climate change laws. Collaborations with international organizations and universities could help build the necessary expertise in the country.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya\'s legal framework for addressing climate change is robust and has laid the foundation for <strong>effective action</strong>. However, challenges such as <strong>limited financial resources, poor institutional coordination, and capacity gaps</strong> must be addressed to ensure that the country can meet its climate change commitments and effectively mitigate and adapt to the changing climate. Through enhanced international cooperation, better resource allocation, and improved public engagement, Kenya can continue to make progress in its fight against climate change and build a sustainable, climate-resilient future for its citizens.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">For more information and/or assistance in matters relating to maritime law, contact us via&nbsp;<a href=\"mailto:info@gmorinaadvocates.org\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinaadvocates.org</strong></a>&nbsp;and/or&nbsp;<strong>+254786437754.</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">All rights reserved for&nbsp;<strong>G.M ORINA &amp; CO. ADVOCATES</strong></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;</p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(10, 'Establishment of an Export Processing Zone Enterprise', 'Godfrey Orina', '2025-04-22', '1745337722987.jpg', '<p class=\"ql-align-justify\">An export processing zone enterprise refers to a <strong>corporate body</strong> which has been <strong>granted a valid licence by the Export Processing Authority.</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">An Export Processing Zone Enterprise shall be only be granted a licence <strong>if </strong>the proposed business enterprise:</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>is incorporated in Kenya</strong>, whether or not it is wholly foreign-owned, for the sole 		 purpose of producing goods or services for export within an export processing zone;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;ii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>proposes to engage</strong> in any activity or activities <strong>eligible </strong>to be undertaken by an export processing zone enterprise in the export processing zone;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>shall not have a deleterious impact on the environment, </strong>or engage in <strong>unlawful activities</strong>, impinging on <strong>national security or may prove to be a health hazard;</strong> and</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iv.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;conducts its business in <strong>accordance with the laws</strong> for the time-being in force.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">For more information and/or assistance in matters relating to establishment and/or licencing of an export processing zone enterprise, contact us via <a href=\"mailto:info@gmorinaadvocates.org/godfrey@gmorinaadvocates.org\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinaadvocates.org/godfrey@gmorinaadvocates.org</strong></a><strong> and/or +254 786437754.&nbsp;</strong></p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(12, 'Process of Incorporation of a Trust in Kenya', 'Godfrey Orina', '2025-05-01', '1746091433167.jpg', '<p class=\"ql-align-justify\">A trust is a fiduciary relationship where a <strong>settlor </strong>gives <strong>a trustee</strong> <strong>a right to hold title</strong> <strong>to property or assets </strong>for the benefit of a <strong>beneficiary.</strong> </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-center\"><strong>Who can make an application for incorporation of a Trust?</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-justify\">1.&nbsp;&nbsp;&nbsp;An Advocate;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">2.&nbsp;&nbsp;&nbsp;A Trustee;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">3.&nbsp;&nbsp;&nbsp;An Enforcer; or</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">4.&nbsp;&nbsp;&nbsp;The Settlor. </p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><strong>Requirements required for incorporation of a trust in Kenya. </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The following particulars are required for the incorporation of a trust in Kenya: -</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>proposed name</strong> which must have the word “Registered Trustees” at the end;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;ii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>objects or purpose</strong> of the trust;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;a duly completed <strong>application for incorporation</strong>;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;iv.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;a <strong>petition</strong> to have the trust incorporated;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;v.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;a <strong>duly registered trust deed</strong> and <strong>Constitution;</strong></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;vi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>statement of donor funding/commitment</strong>;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;vii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>title deed belonging to the trust</strong> or one of the trustees or other documents of asset or property ownership;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;viii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>current search</strong> indicating ownership position of <strong>assets listed;</strong></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><strong>&nbsp;&nbsp;ix.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;financial statement</strong> of the organization or of one trustee such as <strong>a current bank statement;</strong></p><p class=\"ql-align-justify\"><strong>&nbsp;</strong></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;x.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>minutes</strong> appointing the trustees;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;xi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>brief summary</strong> of the trust;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;xii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>curriculum vitae</strong> of the trustees or employees;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;xiii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>diagrammatic representation</strong> of the common seal;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>xiv.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;certified copies of ID, KRA PIN and passport photos of the Settlor, Trustees, beneficiaries and enforcers (if any) </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><span style=\"background-color: white; color: rgb(55, 65, 81);\">For more information and/or assistance in matters relating to incorporation of a trust, contact us via&nbsp;</span><a href=\"mailto:info@gmorinaadvocates.org/godfrey@gmorinaadvocates.org\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: blue;\"><strong>info@gmorinaadvocates.org/godfrey@gmorinaadvocates.org</strong></a><strong style=\"color: rgb(55, 65, 81); background-color: white;\">&nbsp;and/or +254 786437754.&nbsp;</strong></p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13, 'Registration of a Foreign Company in Kenya', 'G.M Orina & Co. Advocates', '2025-05-02', '1752045978245.jpg', '<p class=\"ql-align-justify\">Kenya, presents a compelling landscape for foreign businesses seeking expansion.<sup> </sup>Its robust economy, strategic geographical location, and a steadily growing consumer base make it an attractive destination for foreign direct investment (FDI).<sup>&nbsp;</sup>The primary legal framework governing the registration and operation of foreign companies in Kenya is the <strong>Companies Act, 2015 (Act No. 17 of 2015. </strong>Under Section 3 of the Companies Act, a foreign company is any company incorporated outside Kenya.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[1]</a> Foreign companies intending to do business in Kenya must comply with the legal requirements under the Companies Act, 2015, primarily through registration as a branch of a foreign company or establishing a local subsidiary. Registration ensures legal recognition, tax compliance, and the ability to enforce contracts within the country.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>The Process of Registration of a Foreign Company in Kenya</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Registering a foreign company in Kenya, specifically as a branch, involves a structured process primarily managed by the Business Registration Service (BRS) through the eCitizen portal.<sup> </sup>The process, while increasingly streamlined, requires meticulous attention to detail and adherence to statutory requirements.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">1.&nbsp;&nbsp;&nbsp;<strong>Name Reservation</strong>-The initial step involves conducting a name search and reservation. This is crucial to ensure the proposed name for the Kenyan branch is unique and available for registration. The application is submitted online via the eCitizen portal, and upon approval, a name reservation letter is issued. Section 976 provides that the name of such company can be the name of the company under the law of the country or territory in which it is incorporated; or an alternative name specified in accordance with section 977.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[2]</a></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">2.&nbsp;&nbsp;&nbsp;<strong>Application for Registration of a Foreign Company (Form FC2)</strong>- This is the core application form for registering a foreign company. It requires comprehensive details about the foreign company, including its registered name, its proposed name in Kenya (if different), and its business activities.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[3]</a></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">3.&nbsp;&nbsp;&nbsp;<strong>Submission of Certified Documents</strong>- A critical aspect of the registration process is the submission of certified copies of the foreign company\'s foundational documents as provided for Under Section 975 of the Companies Act.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[4]</a> These include:</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">a)&nbsp;&nbsp;<strong>Certified copy of the Certificate of Incorporation/Registration, issued by the company\'s country of origin</strong>. It must be notarized or certified by the Registrar of Companies in that country. If the original is not in English, a certified translation is required.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">b)&nbsp;&nbsp;<strong>Certified copy of the Company\'s Constitution (Memorandum and Articles of Association)</strong> which outlines the company\'s objectives, powers, and internal regulations. It also requires notarization/certification and translation if necessary.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><strong>c)&nbsp;&nbsp;List of Directors and Shareholders</strong>. This list should include their <strong>full names, contact details (email, phone, postal, and residential addresses), passport biodata, and passport photos.</strong></p><p class=\"ql-align-justify\"><strong>&nbsp;</strong></p><p class=\"ql-align-justify\">d)&nbsp;&nbsp;<strong>Notice of Registered Office in Kenya (Form FC4).</strong> This form specifies the physical address of the <strong>company\'s principal place of business in Kenya</strong>, including the building name, plot number, road, and county.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[5]</a></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">e)&nbsp;&nbsp;<strong>Notice specifying opening hours of company</strong> (Form FC6). This form details the proposed operating hours of the branch.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">4.&nbsp;&nbsp;&nbsp;<strong>Appointment of a Local Representative</strong>- Section 979 of the Act provides for the appointment of <strong>at least one local representative</strong>. This individual must be a Kenyan citizen residing in Kenya. The local representative acts as the primary contact for legal and administrative matters, ensuring compliance with the Companies Act and facilitating communication with government agencies. Their details (full names, ID and KRA PIN copies, passport photo, and contact information) must be provided. The company shall lodge with the Registrar for registration a notice of the appointment of the Local representative.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[6]</a></p><p class=\"ql-align-justify\"><strong>Section 981, </strong>clarifies the local representative\'s accountability for ensuring the company\'s compliance with the Companies Act.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">5.&nbsp;&nbsp;&nbsp;<strong>Payment of Prescribed Fees</strong>- Various fees are associated with the registration process, including name reservation fees and registration fees for the branch. These payments are made through the eCitizen platform.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">6.&nbsp;&nbsp;&nbsp;<strong>Issuance of Certificate of Compliance</strong>- Once the Registrar of Companies is satisfied that all requirements have been met, a Certificate of Compliance is issued. This document legally recognizes the foreign company\'s branch in Kenya, allowing it to commence operations.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">7.&nbsp;&nbsp;&nbsp;<strong>Post-Registration Compliance</strong>- Upon obtaining the Certificate of Compliance, the company must undertake several further registrations to ensure full legal operation:</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">a)&nbsp;&nbsp;<strong>Taxpayer Registration (KRA PIN)-</strong> The company must register for a Personal Identification Number (PIN) with the Kenya Revenue Authority (KRA) for corporate tax, VAT, and PAYE purposes. Directors and employees will also need individual PINs.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">b)&nbsp;&nbsp;<strong>Social Security Registration (NSSF).</strong> Registration with the National Social Security Fund (NSSF) is mandatory for employers to remit contributions for their employees\' social security benefits.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">c)&nbsp;&nbsp;Social Health Insurance (SHA, formerly NHIF). Employers are required to contribute to the national health insurance scheme for their employees through the Social Health Authority (SHA).</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">d)&nbsp;&nbsp;<strong>Business Permit</strong>. A unified business permit must be obtained from the relevant County Government where the business will operate.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">e)&nbsp;&nbsp;<strong>Industry-Specific Licenses</strong>. Depending on the nature of the business, additional licenses or certifications from specific regulatory bodies (e.g., National Construction Authority, Communications Authority of Kenya) may be required.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Beyond the Companies Act, other crucial legislative frameworks impact foreign companies, include the <strong>Income Tax Act</strong> which<strong> </strong>governs corporate tax, withholding tax, and Value Added Tax (VAT) obligations for foreign companies on income accrued or derived in Kenya. The National Social Security Fund Act<strong> </strong>mandates employer contributions to the NSSF. Social Health Insurance Act<strong> </strong>requires employer contributions to the national health insurance scheme. The Investment Promotion Act provides a framework for promoting and facilitating investment in Kenya.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Impact on Foreigners (Foreign Companies and Individuals)</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The registration process and subsequent operation in Kenya have significant implications for foreign companies and the foreign individuals involved:</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Registration grants foreign companies’ legal recognition and protection under Kenyan law</strong>. This allows them to enter into contracts, own property, sue, and be sued in Kenya, providing a secure operating environment.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;ii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Registration unlocks access to Kenya\'s rapidly growing consumer market and positions the company to tap into the wider East African Community (EAC) market.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;While streamlined, the registration and ongoing compliance requirements can be a burden, especially for companies unfamiliar with Kenyan legal and regulatory nuances. This often necessitates engaging local legal and financial advisors.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;iv.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Foreign companies are subject to Kenyan tax laws. While subsidiaries generally face a 30% corporate income tax rate, branches of foreign companies are typically taxed at a higher rate of 37.5% on their Kenyan-sourced income. This higher tax rate can be a disadvantage compared to establishing a subsidiary.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><strong>&nbsp;&nbsp;&nbsp;v.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;The local representative bears a significant responsibility for ensuring the foreign company\'s compliance with the Companies Act, which can entail personal liability for default.</strong></p><p class=\"ql-align-justify\"><strong>&nbsp;</strong></p><p class=\"ql-align-justify\">&nbsp;&nbsp;vi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Potential for Incentives can be granted depending on the sector and scale of investment, foreign companies may be eligible for various investment incentives offered by the Kenyan government, such as those under Export Processing Zones (EPZs) or Special Economic Zones (SEZs), though these are often more readily available to locally incorporated entities (subsidiaries).</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Impact on Kenya\'s Economy</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The registration of foreign companies has a multifaceted and generally positive impact on Kenya\'s economy. This includes:</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Increased Foreign Direct Investment (FDI).</strong> A clear and streamlined registration process encourages more foreign companies to establish a presence, leading to increased FDI.<sup> </sup>This injects capital into the economy, fuels economic growth, and strengthens the country\'s financial position.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;ii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Job Creation:</strong> Foreign companies create direct and indirect employment opportunities for Kenyans, from managerial positions to operational staff. This helps reduce unemployment and improve livelihoods.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Technology Transfer and Skills Development:</strong> Foreign companies often bring advanced technologies, modern management practices, and specialized skills. This facilitates knowledge transfer to the local workforce, enhancing their capabilities and contributing to overall human capital development.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;iv.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Increased Tax Revenue</strong>:&nbsp;The registered foreign companies become taxpayers in Kenya, contributing to government revenue through corporate income tax, VAT, PAYE, and other levies. This revenue supports public services and infrastructure development.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;v.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Market Expansion and Competition.</strong> The entry of foreign companies introduces new products, services, and business models, diversifying the market and fostering healthy competition. This can lead to improved quality, lower prices, and greater choice for consumers.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;vi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Infrastructure Development.</strong> Some foreign investments, particularly in sectors like energy, manufacturing, and telecommunications, often involve significant infrastructure development, benefiting the wider economy.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Despite these benefits, potential negative impacts, though less common, could include <strong>increased competition for local businesses, potential exploitation of natural resources without adequate environmental safeguards</strong>, or <strong>profit repatriation</strong> without significant local reinvestment. However, robust regulatory frameworks and oversight aim to mitigate such risks.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">In conclusion, the registration of foreign companies in Kenya <strong>represents a deliberate effort by the government to attract foreign investment and stimulate economic growth</strong>. While the process demands diligence and compliance with specific legal provisions, it ultimately provides foreign entities with a legitimate and protected avenue to participate in Kenya\'s dynamic economy, fostering a mutually beneficial relationship.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">For more information and/or assistance in matters relating to incorporation of a foreign company, contact us via <a href=\"mailto:info@gmorinadvocates.org/godfrey@gmorinaadvocates.org\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinadvocates.org/godfrey@gmorinaadvocates.org</strong></a><strong> and/or +254786437754.</strong></p><p><br></p><p><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[1]</a> Companies Act, No 17 of 2015, s 3 (Laws of Kenya).</p><p><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[2]</a> Companies Act, No 17 of 2015, s 976(2) (Laws of Kenya).</p><p><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[3]</a> Companies Act, No 17 of 2015, s 975 (Laws of Kenya).</p><p><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[4]</a> Companies Act, No 17 of 2015, s 975 (3) (Laws of Kenya).</p><p><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[5]</a> Companies Act, No 17 of 2015, s 983 (Laws of Kenya).</p><p><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[6]</a> Section 980&nbsp;</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14, 'Artificial Intelligence & Standard of Care in Law', 'G.M Orina & Co. Advocates', '2025-05-05', '1752049370820.jpg', '<p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The rapid advancement and integration of Artificial Intelligence (AI) across diverse sectors, <strong>such as healthcare</strong>, has <strong>undeniably revolutionized capabilities and efficiencies.</strong> However, this technological leap also presents profound legal and ethical dilemma, particularly concerning the \"<strong>standard of care</strong>.\" Traditionally, the standard of care dictates the <strong>level of caution and competence</strong> expected from a reasonable person or professional in a given situation. AI\'s unique characteristics <strong>presents a challenge to existing legal frameworks</strong> and necessitate <strong>a re-evaluation of how culpability and responsibility are assigned when AI-driven systems cause harm.</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>The Traditional Standard of Care and AI\'s Disruption</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">In law, the standard of care is the cornerstone <strong>of negligence claims</strong>. The question is ‘<strong><em>what would a reasonably prudent person have done under similar circumstances</em></strong><em>?”</em> If an individual\'s actions fall below this standard, and that failure causes harm, they can be held liable. This human-centric approach is ill-equipped for AI for several reasons.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">According to Professor Samir Rawashdeh, he explains <strong><em>the \"Black Box\"</em></strong> Problem in those many advanced AI systems, particularly those relying on <strong>deep learning, operate as \"black boxes.\"</strong> Their decision-making processes are so complex that even their creators may struggle to fully explain <em>why</em> a particular output or recommendation was generated. This inherent capacity makes it exceedingly difficult to assess if an <strong>AI system \"acted\" reasonably, or to pinpoint where a \"defect\" in its logic might lie.</strong><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>[1]</strong></a></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Unlike static software, AI systems <strong>can learn and evolve post-deployment based on new data</strong>. This dynamic nature means that the system that caused harm might not be identical to the one initially designed or even the one tested. This <strong>continuous evolution</strong> complicates the idea of <strong>a fixed \"standard\"</strong> against which the AI\'s behavior can be measured at the time of an incident.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[2]</a></p><p class=\"ql-align-justify\">AI development and deployment involves a complex system of actors who include <strong>data providers, algorithm developers, system integrators, deployers, and end-users</strong>. When an AI system gives an error, attributing fault to a single entity becomes a formidable challenge. Is it the developer for flawed code, the data provider for biased training data, the deployer for improper implementation, or the user for overriding a correct AI recommendation?<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[3]</a></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The existing legal principles on negligence and product liability are now being stretched to <strong>accommodate AI-related harms</strong>. On negligence while it is still applicable to human actors overseeing AI, applying negligence directly to AI is problematic. <strong>Courts may struggle to define a \"reasonable AI\"</strong> or to ascertain a duty of care for a non-human entity. However, human operators (such as, a doctor using an AI diagnostic tool) will continue to be judged based on the standard of care expected of their profession, including the <strong>responsible use and oversight of AI tools</strong>. <strong>If a doctor blindly follows a flawed AI recommendation without exercising their professional judgment, they could still be liable for medical malpractice.</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The doctrine of product liability holds manufacturers <strong>strictly liable</strong> <strong>for injuries caused by defective products, regardless of fault</strong>. The key question here is whether an AI system, particularly software or an AI-driven component, can be classified as <strong>a \"product</strong>.\" If so, is the defect in its design, manufacture (i.e., its coding or training data), or a failure to warn? The evolving nature of AI makes proving <strong>a \"design defect</strong>\" particularly challenging, as the \"design\" might be constantly changing through learning. Some legal scholars advocate for <strong>stricter product liability</strong> for AI, especially for high-risk autonomous systems, to incentivize developers to prioritize safety from the outset.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[4]</a></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">If an AI system provides a service (e.g., a legal research tool offering advice), traditional service liability principles might apply, focusing on <strong>the professional standard of care</strong> in delivering that service. However, this still circles back to the difficulty of assessing the AI\'s own \"competence.\"</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Emerging Laws and Regulatory Approaches</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Recognizing <strong>the inadequacy</strong> of existing laws, jurisdictions worldwide are actively developing new legal frameworks and regulatory approaches to address AI. <strong>The European Union AI Act</strong>,<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[5]</a> provides a risk-based approach. It categorizes AI systems based on their potential to cause harm (e.g., u<strong>nacceptable risk, high-risk, limited risk, minimal risk)</strong>. High-risk AI systems (e.g., those used <strong>in critical infrastructure, medical devices, law enforcement</strong>) face stringent requirements, including <strong>mandatory risk assessments</strong>, <strong>human oversight, robust data governance, transparency obligations, and conformity assessments</strong> before they can be placed on the market. This aims to ensure safety and accountability by imposing greater burdens on systems with higher potential for harm.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[6]</a></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Beyond the EU AI Act, efforts are underway to specifically address <strong>civil liability for AI.</strong> The proposed <strong>EU AI Liability Directive</strong>, though facing some legislative hurdles, is aimed to ease the burden of proof for victims of AI-related harm, for instance, by introducing <strong>rebuttable presumptions of causation</strong> for certain high-risk AI systems. Such initiatives seek to balance fostering innovation while ensuring adequate consumer protection.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Despite these efforts, significant challenges remain. <strong>Establishing causation can be complex</strong> when AI is involved in a chain of events leading to harm. The foreseeability of AI\'s behavior, particularly for autonomous learning systems, is also difficult to prove. Furthermore, the global nature of AI development and deployment means that a patchwork of national and regional regulations could create <strong>regulatory fragmentation</strong>, thus hinder innovation and create enforcement challenges. The evolution of AI and the standard of care will likely involve a continuous interplay between technological advancements, legal innovation, and societal expectations.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">In conclusion, Artificial Intelligence demands <strong>a fundamental re-evaluation of legal principles, especially the standard of care.</strong> The journey to effectively regulate AI and establish clear liability rules is complex and ongoing. It requires <strong>a multidisciplinary approach</strong>, blending <strong>legal expertise with technological understanding and ethical foresight,</strong> to ensure that AI\'s immense potential is harnessed responsibly and equitably within the bounds of justice and accountability.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">For more information and/or assistance in matters relating to Artificial Intelligence &amp; Standard of Care in Law, contact us via <a href=\"mailto:info@gmorinadvocates.org\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinadvocates.org</strong></a><strong> </strong><a href=\"mailto:/godfrey@gmorinaadvocates.org\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>/godfrey@gmorinaadvocates.org</strong></a><strong>&nbsp;and/or +254786437754.</strong></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[1]</a> University of Michigan-Dearborn, \'AI’s Mysterious “Black Box” Problem Explained\' (University of Michigan-Dearborn, 7 June 2023) &lt;https://umdearborn.edu/news/ais-mysterious-black-box-problem-explained&gt; accessed 19 June 2025.</p><p class=\"ql-align-justify\"><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[2]</a> Ashraf MH Taha, Zakaria KD Alkayyali, Qasem MM Zarandah, Bassem S Abu-Nasser and Samy S Abu-Naser, \'The Evolution of AI in Autonomous Systems: Innovations, Challenges, and Future Prospects\' (2024) 8(10) International Journal of Academic Engineering Research (IJAER) 1 &lt;http://www.ijeais.org/ijaer&gt; accessed 19 June 2025.</p><p class=\"ql-align-justify\"><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[3]</a> Trilateral Research, ‘Who Is Responsible for Artificial Intelligence Governance?’ (Trilateral Research, 3 November 2020) &lt;https://trilateralresearch.com/artificial-intelligence/who-is-responsible-for-artificial-intelligence-governance&gt; accessed 19 June 2025.</p><p class=\"ql-align-justify\"><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[4]</a> BIICL, ‘Overview of the Legal and Institutional Framework in the United Kingdom’ (August 2004) &lt;https://www.biicl.org/documents/267_overview_uk_-_aug_2004.pdf&gt; accessed 19 June 2025.</p><p class=\"ql-align-justify\"><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[5]</a> European Commission, ‘AI Act Explorer’ (Artificial Intelligence Act, 2024) &lt;https://artificialintelligenceact.eu/ai-act-explorer/&gt; accessed 19 June 2025.</p><p class=\"ql-align-justify\"><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[6]</a> Trail ML, ‘EU AI Act: How Risk Is Classified’ (Trail ML, 2024) &lt;https://www.trail-ml.com/blog/eu-ai-act-how-risk-is-classified&gt; accessed 19 June 2025.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `articles` (`id`, `title`, `author`, `date`, `image`, `description`, `subtitle1`, `description1`, `desc1l1`, `desc1l2`, `desc1l3`, `desc1l4`, `desc1l5`, `subtitle2`, `description2`, `subtitle3`, `description3`, `desc3l1`, `desc3l2`, `desc3l3`, `desc3l4`, `desc3l5`, `description5`) VALUES
(15, 'Current Construction Trends', 'G.M Orina & Co. Advocates', '2025-05-06', '1752055764288.jpg', '<p class=\"ql-align-justify\">The global construction industry is undergoing a profound transformation, driven <strong>by rapid technological innovation</strong>, an urgent push for <strong>environmental sustainability</strong>, and evolving project delivery paradigms. This dynamic environment necessitates a keen understanding of both <strong>international advancements and localized regulatory framework</strong>. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya, is <strong>actively engaging with these global shifts</strong>, modernizing its <strong>legal and operational frameworks to foster a safer, more efficient, and sustainable built environment</strong>. However, with these advancements comes new <strong>legal, regulatory, and contractual complexities that both developers and legal practitioners must navigate</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Sustainability</strong> has become central to modern construction.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[1]</a> The construction industry is increasingly driven by environmental concerns, leading to a focus on sustainable and resilient approaches. Developers are increasingly adopting <strong>environmentally conscious practices</strong> such as <strong>the use of eco-friendly materials, energy-efficient systems, and water recycling technologies.</strong> Institutions like the National Environment Management Authority (NEMA) now play a bigger role in regulating environmental impacts, and Environmental Impact Assessment (EIA) reports are legally required before major projects begin under the Environmental Management and Co-ordination Act (EMCA).</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Digital tools such as <strong>Building Information Modelling (BIM</strong>), <strong>drones, and AI-powered planning systems</strong> are transforming how projects are conceptualized and managed. BIM has emerged as a prominent and essential tool across <strong>the Architecture, Engineering, and Construction (AEC) industries</strong>, fundamentally changing how teams share information, manage workflows, and execute processes. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">While these technologies improve efficiency and reduce errors, they also <strong>raise legal concerns around data ownership, cybersecurity, and liability in cases of system failure or flawed design.</strong> Kenya’s Data Protection Act, 2019, and related ICT laws are <strong>increasingly relevant in regulating the digital side of construction.</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya continues to prioritize infrastructure development through <strong>Public-Private Partnerships (PPPs),</strong> especially <strong>in roads, housing, and energy</strong>. The PPP Act introduces streamlined frameworks for <strong>project approval and implementation, enhancing investor confidence.</strong> Be that as it may, PPPs come with risks such as <strong>delayed government payments, land acquisition disputes, and unclear risk-sharing arrangements</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The construction industry is directly impacted by <strong>climate change</strong>, <strong>facing escalating damage and insurance costs from extreme weather events and gradual climate shifts</strong>.<sup> </sup>Consequently, companies are increasingly incorporating climate resiliency into new and retrofitted construction. This involves adopting climate-resilient designs and materials, and ensuring appropriate health and safety conditions for workers during adverse weather. The focus on <strong>\"climate-resilient construction</strong>\" signifies a shift from merely building structures to designing and constructing them to withstand future environmental shocks. This is a <strong>proactive rather than reactive approach</strong>, embedding resilience into the very fabric of infrastructure to mitigate long-term financial and physical risks associated with a changing climate.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The <strong>Affordable Housing Programme</strong> under the government’s Big Four Agenda has led to the emergence of large-scale residential construction. However, issues around <strong>land tenure, compulsory acquisition, and unclear titling remain common legal hurdles. </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Construction sites are now under <strong>greater scrutiny</strong> to adhere to occupational health and safety laws. The Occupational Safety and Health Act, 2007<strong>, mandates risk assessments, safety audits, and protective measures for all workers. </strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The oversight of Kenya\'s construction industry involves a multi-layered legal and regulatory structure.<strong> The National Construction Authority Act, 2011</strong> established the National Construction Authority (NCA) with the broad mandate to <strong>regulate, streamline, and build capacity</strong> within the construction industry.<sup> </sup>It aims to <strong>promote growth, standardize practices, and ensure quality across the sector.</strong> The Act mandates crucial processes such as contractor registration, project registration, and worker accreditation. The 2011 Act provides the statutory authority for the NCA\'s extensive regulatory and developmental functions. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>The Physical Planning Act</strong> provides the overarching legal framework for physical planning and development control in Kenya.<sup> </sup>It establishes <strong>Physical Planning Liaison Committees</strong> and grants powers to local authorities to control land use and development. The Act mandates the <strong>preparation and adoption of regional and local physical development plans</strong>, ensuring orderly development. This Act is critical because it dictates the context in which construction occurs, focusing on land use, zoning, and the orderly development of space.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>The Environmental Management and Coordination Act (EMCA), </strong>serves as Kenya\'s comprehensive legislative framework for <strong>promoting sustainable development by integrating environmental considerations into all decision-making processes</strong>. It mandates Environmental Impact Assessments (EIA) and Environmental Management Plans (EMP) for all projects, including construction, to identify and mitigate adverse environmental effects.<sup> </sup>The Act further promotes sustainable resource use and energy efficiency. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The <strong>National Construction Authority is </strong>established by the NCA Act No. 41 of 2011. The NCA serves as the primary body overseeing and coordinating the construction industry in Kenya.<sup> </sup>Its extensive functions include registering and licensing both local and foreign contractors, categorizing them based on contract value to ensure qualified entities undertake projects. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>National Environment Management Authority (NEMA)</strong> is established under the Environmental Management and Co-ordination Act (EMCA) 1999. NEMA is <strong>the principal government agency</strong> responsible for <strong>environmental management in Kenya</strong>.<sup> </sup>Its function in the context of construction includes approving EIAs for any project likely <strong>to have adverse environmental impacts</strong>.<sup> </sup>This requires a report and an EIA Study Report detailing potential impacts and mitigation measures. NEMA\'s power to mandate EIAs and halt non-compliant projects positions it as <strong>a critical regulatory force</strong> for environmental stewardship. This makes environmental responsibility a fundamental legal prerequisite for any construction undertaking.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">County Governments also<strong> </strong>play a crucial role through issuance of construction permits (<strong>building approvals</strong>) that allow projects to legally proceed. This ensures that construction works meet established local standards and regulations<strong>, safeguarding public health and safety</strong>. It is important to note that after obtaining a permit from a county government, projects must then be registered with the NCA, which issues a compliance certificate for commencement of works.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The <strong>National Building Code 2024</strong>,<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[2]</a> replaced the 1968 building regulations.<a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[3]</a><sup> </sup>The NBC 2024\'s updates encompassing <strong>safety, sustainability, digital infrastructure, and accessibility indicates a deliberate and ambitious modernization effort</strong>. This is more than an incremental change; it is a foundational shift designed to address historical issues like collapsing of buildings and align Kenya with global best practices.<sup> </sup>The move to adhere to performance-based regulations is particularly significant as it fosters innovation rather than rigid adherence to outdated methods, while increased penalties signal a serious commitment to enforcement, aiming to overcome a \"weak safety culture\".</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya\'s legal landscape is actively adapting to these global trends, most notably through the comprehensive <strong>National Building Code 2024</strong> and ongoing reviews of the NCA Act. These legislative updates aim to enhance safety, promote sustainability, ensure digital readiness, and improve accessibility. While significant opportunities exist through legislative evolution, private sector leadership in green building, and strategic investments, challenges such as enforcement gaps, high initial costs, and skills deficits must be addressed to fully realize the potential of modern construction in Kenya.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">For more information and/or assistance in matters relating to Current Construction Trends, contact us via <a href=\"mailto:info@gmorinadvocates.org/godfrey@gmorinaadvocates.org\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinadvocates.org/godfrey@gmorinaadvocates.org</strong></a><strong> and/or +254786437754.</strong></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">  <a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[1]</a> SwiftWall, ‘Why Sustainable Construction is So Important’ (SwiftWall, 2024) &lt;https://swiftwall.com/resources/why-sustainable-construction-is-so-important/&gt; accessed 19 June 2025.</p><p class=\"ql-align-justify\"><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[2]</a> 2024 National Building Code (Legal Notice No. 47 of 2024)</p><p class=\"ql-align-justify\"><a href=\"about:blank\" rel=\"noopener noreferrer\" target=\"_blank\">[3]</a> 1968 Building Code (Local Government (Adoptive By-Laws) (Building) Order, 1968)</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16, 'Navigating the Public Private Partnerships Landscape in Kenya   – An Overview – Series 1', 'G.M Orina & Co. Advocates', '2025-04-01', '1752056418581.jpg', '<p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Kenya has in force the Public Private Partnerships Act, a law that provides for <strong>the participation of the private sector</strong> in the <strong>financing, construction, development, operation or maintenance of infrastructure or development projects</strong> through public private partnerships and to streamline the regulatory framework for public private partnerships.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>Object of the Act</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The purpose of this Act, articulated in Section 3, is to: -</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">a.&nbsp;&nbsp;&nbsp;<strong>prescribe the procedures</strong> for the participation of the private sector in the financing, construction, development, operation or maintenance of infrastructure or development projects through public private partnerships;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">b.&nbsp;&nbsp;&nbsp;<strong>harmonize the institutional framework</strong> for the implementation of public private partnership projects;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">c.&nbsp;&nbsp;&nbsp;&nbsp;give effect to Article 227 of the Constitution on <strong>procurement relating to public private partnerships;</strong></p><p class=\"ql-align-justify\"><strong>&nbsp;</strong></p><p class=\"ql-align-justify\">d.&nbsp;&nbsp;&nbsp;<strong>streamline and rationalize</strong> the regulatory, implementation and monitoring mandates of relevant agencies; and</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">e.&nbsp;&nbsp;&nbsp;<strong>provide for a transparent project selection process</strong>, clear procurement structures, reduced regulatory approvals and explained contractual models in order to promote private sector investment.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><strong>Establishment of a Public Private Partnership Committee</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Act establishes a Public Private Partnership Committee which is responsible <strong>for formulating policies on public private partnerships,</strong> <strong>overseeing the implementation of public private partnerships contracts,</strong> <strong><u>approving standardized public private partnership bid documents</u></strong>, <strong>approving feasibility studies</strong>, <strong>approving privately-initiated proposals</strong>, <strong>approving negotiated contract terms, the cancellation of procurements or termination of project agreements and the variation of project agreements</strong> and monitoring the implementation of the Public Private Partnerships Act, including the sustainability of contingent liabilities that may be incurred by a contracting authority for projects approved under the Act. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong><u>Composition of the Public Private Partnership Committee</u></strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Section 6 of the Act provides for the composition of the Public Private Partnership Membership Committee as follows:</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the <strong>Principal Secretary</strong> in the State department responsible for matters relating to <strong>finance</strong>, who shall be the chairperson;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;ii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the <strong>Principal Secretary</strong> in the State department responsible for matters relating to <strong>planning;</strong></p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the <strong>Principal Secretary</strong> in the State department responsible for matters relating to <strong>infrastructure;</strong></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iv.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the <strong>Solicitor – General</strong>;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;v.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;two persons nominated by the <strong>Council of Governors</strong>;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;vi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;three persons, not being public officers, appointed by notice in the Gazette by the Cabinet Secretary; and</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">&nbsp;vii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the <strong>Director General,</strong> who shall be the secretary.</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><strong><u>Establishment and Functions of the Directorate</u></strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The Act has established the Directorate, who work with the Director General, and perform key functions in the <strong>implementation</strong> of a public private partnership project, who are responsible for the following:</p><p class=\"ql-align-justify\"> </p><p class=\"ql-align-justify\">a.&nbsp;&nbsp;&nbsp;<strong>originating, guiding and co-ordinating</strong> the <strong>selection, ranking and prioritization</strong> of public private partnership projects with the public budget framework;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">b.&nbsp;&nbsp;&nbsp;<strong>overseeing project appraisal</strong> and <strong>development activities</strong> of <strong>contracting authorities</strong> including providing technical expertise in the implementation of projects;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><strong>c.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;guiding and advising contracting authorities</strong> in <strong>project structuring, procurement and tender evaluations;</strong></p><p class=\"ql-align-justify\"><strong>&nbsp;</strong></p><p class=\"ql-align-justify\">d.&nbsp;&nbsp;&nbsp;<strong>leading</strong> contracting authorities in <strong>contract negotiations and deal closure</strong>;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">e.&nbsp;&nbsp;&nbsp;on its own motion, <strong>originating and leading in project structuring and procurement, in liaison with a contracting authority</strong>;</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">f.&nbsp;&nbsp;&nbsp;&nbsp;supporting the development of public private partnerships in the country; and</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\">g.&nbsp;&nbsp;&nbsp;overseeing contract management frameworks for projects.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">In our next article on this subject, we shall delve into <strong>project agreements, duties of contracting authorities, determination of duration of public private partnerships agreements, execution of project agreements, prequalification procedures, Governments support measures</strong> and <strong>success fees and recoverable project development costs</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">For more information or assistance in matters relating to public private partnerships, contact us <strong>via </strong><a href=\"mailto:info@gmorinaadvocates.com\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinaadvocates.com</strong></a> and/or <strong>+254786437754.</strong></p><p class=\"ql-align-justify\"><strong>All rights reserved for G.M ORINA &amp; CO. ADVOCATES</strong>. </p><p class=\"ql-align-justify\">&nbsp;</p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(17, 'Admiralty & Maritime Law in Kenya- Functions of the Kenya Maritime Authority – Series 1', 'G.M Orina & Co. Advocates', '2025-04-02', '1752056863383.jpg', '<p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Maritime Law in Kenya is governed by the Kenya Maritime Authority Act, Cap 370 Laws of Kenya. This law establishes the Kenya Maritime Authority (<strong>the “authority.</strong>”) which is responsible for <strong>monitoring, regulating, coordinating and overseeing maritime affairs.</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">The functions of the Authority are set out in <strong>Section 5</strong> of the Act. The authority is tasked to: -</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>administer</strong> and <strong>enforce</strong> the provisions of the Merchant Shipping Act, Cap 389 and any other legislation relating to the maritime sector;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;ii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>co-ordinate </strong>the <strong>implementation</strong> of <strong>policies</strong> relating to maritime affairs and promote the <strong>integration</strong> of such policies into the <strong>national development plan;</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;iii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>advise government</strong> on <strong>legislative</strong> and other measures necessary for the <strong>implementation</strong> of relevant <strong>international conventions, treaties and agreements to which Kenya is a party</strong>;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;iv.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;liase with the <strong>National Electronic Window System</strong> established under Section 3 of the National Electronic Window System Act, Cap 485D to <strong>establish digital and electronic platforms</strong> and <strong>facilitate collaboration with other agencies to promote trade;</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;v.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>undertake</strong> and <strong>coordinate research</strong>, <strong>investigations</strong> and <strong>surveys</strong> in the maritime field;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;vi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>discharge flag state</strong> and <strong>port State responsibilities</strong> in an efficient and effective manner having regard to <strong>international maritime conventions, treaties, agreements</strong> and other instruments to which Kenya is a Party;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;vii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;develop, co-ordinate and manage <strong>a national oil spill contingency plan</strong> for both coastal and inland waters;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;viii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>maintain</strong> and <strong>administer</strong> a ship register;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;ix.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;deal with matters pertaining to <strong>maritime search and rescue</strong> and co-ordinate the activities of the Kenya Ports Authority, the Kenya Navy and other bodies engaged during search and rescue operations;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;x.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>enforce</strong> <strong>safety of shipping, including compliance</strong> with <strong>construction regulations, maintenance of safety standards</strong> and safety navigation rules;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;&nbsp;xi.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;conduct <strong>regular inspection of ships</strong> to ensure maritime safety and prevention of marine pollution;</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;xii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;oversee matters pertaining to the <strong>training, recruitment and welfare of seafarer</strong> and</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">&nbsp;xiii.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>implement </strong>and <strong>undertake</strong> co-ordination in maritime security.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><strong>G.M Orina &amp; Co. Advocates</strong> provides a wide array of <strong>marine-based services</strong> for <strong>vessel owners</strong>, <strong>operators</strong> and <strong>suppliers</strong> including <strong>marine insurance</strong>, <strong>dispute resolution</strong>, <strong>financing construction</strong>, <strong>commercial agreements</strong> and <strong>marine employment law,</strong></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">In our next article, we explore in depth the <strong>key components of maritime</strong> law and delve into <strong>jurisdiction</strong> and <strong>procedure</strong> in <strong>maritime cases.</strong></p><p class=\"ql-align-justify\"><strong><span class=\"ql-cursor\">﻿</span></strong></p><p class=\"ql-align-justify\">For more information and/or assistance in matters relating to maritime law, contact us via <a href=\"mailto:info@gmorinaadvocates.org\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>info@gmorinaadvocates.org</strong></a> and/or <strong>+254786437754.</strong></p><p class=\"ql-align-justify\">All rights reserved for <strong>G.M ORINA &amp; CO. ADVOCATES</strong></p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

