INSERT INTO `practice_areas` (`id`, `title`, `description`, `image`, `areas_of_focus`, `created_at`) VALUES
(0, 'Litigation & Dispute Resolution', 'Our Litigation & Dispute Resolution practice focuses on solving disputes relating to employment and labour relations, environment and land disputes, constitutional human rights law, family and succession law and procurement disputes.\r\nOur team is well equipped with skills and knowhow to guide our clients through the dispute resolution process.', '/uploads/1744138148497.jpg', ' Constitutional & Human Rights Law Criminal Litigation Family & Succession Law Arbitration & Mediation Defamation Law Policy Formulation & Legislative Drafting', '2025-04-08 18:49:08'),
(0, 'Technology, Intellectual Property (IP) & Internet Law', 'Our Technology, Intellectual Property (IP) & Internet Law practices focus on advising tech-companies on the legal principles and legislation that govern the use of internet in all its forms.\r\nWe also advise tech-companies and individuals on their intangible assets that range from literary works to new technologies through patent, copyright and trademark registration.', '/uploads/1744138188441.jpg', 'We are currently advising a technological social enterprise developing edge technology, leveraging the power of machine learning and artificial learning and artificial intelligence, to address the communication barrier between the deaf and the hearing/blind, enabling a two-way communication with no need of the hearing/blind understanding sign language.', '2025-04-08 18:49:48'),
(0, 'Corporate & Commercial Law', 'We advise on modalities of setting up new businesses, handling mergers and sale disputes, directors liability and privacy.', '/uploads/1744138266792.jpg', 'We draft, advise and review contracts that prevent disputes to help solidfy relationships and commitments between parties. We advise entrepreneurs, investors, shareholders and financiers on how to select the best form of financing or restructuring. We advise individuals on how to avert bankruptcy, restart, reorganize, analyse risk and manage liability.', '2025-04-08 18:51:06'),
(0, 'Real Estate & Property Law', 'We provide support for home buyers, investors, developers, local authorities, banks and housing corporations.', '/uploads/1744138324561.jpg', 'Environmental planning and compliance with regulations, licenses, tenders and public private partnerships. Registration/recording of conveyances, leases and real estate security interests.', '2025-04-08 18:52:04'),
(0, 'Aviation Law & Practice', 'We advise on a full range of aviation issues including major loss, emergency response and liability as well as non-contentious work including regulation, finance and employment.', '/uploads/1744138369609.jpg', 'Fleet procurement Commercial Dispute Resolution Debt Recovery Environmental Claims/Toxic exposure Finance & Leasing', '2025-04-08 18:52:49'),
(0, 'Procurement Law', 'We offer legal representation and advise entities on how to resolve disputes/potential disputes that arise from the loss/damage suffered due to breach of duty imposed on a procuring entity by the Public Procurement and Disposal Act, 2015.', '/uploads/1744138423788.jpg', 'procurement planning procurement processing Inventory and asset management diposal of assets contract management', '2025-04-08 18:53:43'),
(0, 'IT, Data Protection & Crypto', 'Our IT, Data Protection & Cryptocurrency Law practice provides specialized legal support in managing the challenges and opportunities that arise from technology, privacy regulations, and digital assets. We assist clients in navigating complex areas such as IT agreements, data privacy laws, and cryptocurrency compliance.\r\nWith a strong foundation in IT law, we help businesses secure technology contracts, manage software licensing, and address cybersecurity risks.', '/uploads/1744138497870.jpeg', ' Technology & Software Licensing Cybersecurity Compliance Data Privacy (GDPR & CCPA) Cryptocurrency Taxation & Disputes Blockchain & Cryptocurrency Regulation Data Breach Response', '2025-04-08 18:54:57'),
(0, 'Family, Marriage & Succession', 'Our Family, Marriage & Succession Law practice offers comprehensive legal support in all matters relating to family relationships, marriage, and inheritance. We are committed to helping clients navigate personal and sensitive legal challenges with clarity and compassion.\r\nIn marriage and matrimonial disputes, we offer advice on spousal support, property division, and settlement agreements. In the area of succession law, we guide clients through estate planning, drafting wills, and managing probate processes.', '/uploads/1744138604255.jpeg', ' Divorce & Separation Child Custody & Support Inheritance Disputes Estate Planning & Will Drafting Family Mediation & Dispute Resolution Spousal Support & Property Division', '2025-04-08 18:56:44'),
(0, 'Notarial Services & Certificates', 'Document Notarization\r\nPowers of Attorney & Affidavits\r\nReal Estate Deeds & Contracts\r\nCorporate Notarial Services\r\nVerification of Signatures & Identity\r\nCertificates of Good Standing', '/uploads/1744138722042.jpg', 'Our Notarial Services & Certificates practice offers essential legal support in the authentication and verification of documents, ensuring that our clients meet the requirements for various transactions and legal processes. We provide reliable notarial services to both individuals and businesses, facilitating smooth legal operations and compliance. We assist clients with the preparation and notarization of important documents, including powers of attorney, affidavits, contracts, and property deeds. Our notarial services help ensure that these documents are legally binding and recognized by relevant authorities.', '2025-04-08 18:58:42'),
(0, 'Investment & Franchise', 'Our Investment & Franchise Law practice is dedicated to providing strategic legal guidance to businesses and individuals involved in investment and franchise ventures. We help clients structure, negotiate, and execute investment deals, ensuring that their interests are protected and aligned with legal and regulatory frameworks.\r\nIn investment law, we advise clients on various forms of business investments, including private equity, venture capital, and joint ventures. In the franchise sector, we provide comprehensive support for both franchisors and franchisees. Our services range from franchise agreement drafting and review to compliance with local and international franchise regulations.', '/uploads/1744138804681.jpg', 'Private Equity & Venture Capital Intellectual Property Protection in Franchising Investment Agreements & Structuring Investment Due Diligence Arbitration & Mediation in Investment Disputes', '2025-04-08 19:00:04');

