INSERT INTO `team_members` (`id`, `full_name`, `position`, `email`, `phone`, `bio`, `profile_picture`) VALUES
(6, 'Godfrey Orina', 'Managing Partner', 'godfrey@gmorinaadvocates.org', '0786437754', 'Godfrey is an Advocate of the High Court of Kenya and the Managing Partner of G.M Orina & Co. Advocates. He specializes in Litigation and Dispute Resolution with a particular focus on Constitutional Law, Commercial Litigation and Tax Law.', '/uploads/1743417291594.jpg'),
(12, 'Anne Wanjiru', 'Administrator ', 'anne@gmorinaadvocates.org', '0786437754', 'Anne is a proficient professional, and has worked in various sectors.She holds a diploma in Information Technology [IT], has worked with different organizations and companies across the country. She manages and handles the daily business operations of the firm to support theday-­‐to-­‐day activities. Anne joined G.M Orina and Co. Advocates in 2024.', '/uploads/1743690869555.jpg'),
(13, 'Andrew Wanga', 'Senior Partner', 'andrew@gmorinaadvocates.org', '0786437754', 'Andrew is a senior partner at G.M Orina & Co. Advocates. He specializes in Commercial Law, Real Estate Law and Financial Technology.', '/uploads/1743422754215.jpeg'),
(14, 'John Wekesa', 'Senior Partner', 'john@gmorinaadvocates.org', '0786437754', 'John is a noted thought leader and expert in engineering and construction law, tax law, employment and litigation. He is also a human rights defender and a trusted adviser on financial technology.', '/uploads/1743422816184.jpeg'),
(15, 'Neema Joanne', 'Senior Parner', 'neema@gmorinaadvocates.org', '0786437754', 'Neema Joanne is an Advocate of the High Court of Kenya and Senior Partner at G.M Orina & Co. Advocates. She holds a Bachelor of Laws Degree from Kisii University, Diploma in Law from Kenya School of Law and is currently pursuing Masters of Law at the University of Nairobi', '/uploads/1743422850365.jpg');

